  ('3', '2', '1', 'item 3', '1', '4', '2.50', '15.000', '1.50', '3.00', '10.00', '2020-06-15 12:00:00.000000'),
  ('4', '3', '1', 'item 4', '1', '4', '2.50', '15.000', '1.50', '3.00', '10.00', '2020-06-15 11:00:00.000000'),
  ('5', '4', '1', 'item 5', '1', '4', '2.50', '15.000', '1.50', '3.00', '10.00', '2020-06-15 09:00:00.000000'),
