CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM integration.get_sale_updates('2020-06-15 11:00:00.000000'::timestamp, '2020-06-15 13:00:00.000000'::timestamp);
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['Invoice Date Key', 'Delivery Date Key', 'WWI Invoice ID', 'Description', 'Package', 'Quantity', 'Unit Price', 'Tax Rate', 'Total Excluding Tax', 'Tax Amount', 'Profit', 'Total Including Tax', 'Total Dry Items', 'Total Chiller Items', 'WWI City ID', 'WWI Customer ID', 'WWI Bill To Customer ID', 'WWI Stock Item ID', 'WWI Saleperson ID', 'Last Modified When']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 dry and chiller lines split Quantity; Total Excluding Tax = ExtendedPrice - TaxAmount; UnitPrice and…', got, ARRAY['Invoice Date Key', 'Delivery Date Key', 'WWI Invoice ID', 'Description', 'Package', 'Quantity', 'Unit Price', 'Tax Rate', 'Total Excluding Tax', 'Tax Amount', 'Profit', 'Total Including Tax', 'Total Dry Items', 'Total Chiller Items', 'WWI City ID', 'WWI Customer ID', 'WWI Bill To Customer ID', 'WWI Stock Item ID', 'WWI Saleperson ID', 'Last Modified When']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('2020-06-14', NULL, '1', 'dry item ', 'Each', '4', '2.5', '15', '8.5', '1.5', '3', '10', '4', '0', '10', '1', '2', '1', '3', '2020-06-15 12:00:00.000000'),
  ('2020-06-14', NULL, '1', 'item 2', 'Each', '4', NULL, '15', '8.5', '1.5', '3', '10', '0', '4', '10', '1', '2', '2', '3', '2020-06-15 12:00:01.000000'),
  ('2020-06-14', '2020-06-15', '4', 'item 5', 'Each', '4', '2.5', '15', '8.5', '1.5', '3', '10', '4', '0', '10', '1', '1', '1', '3', '2020-06-15 13:00:00.000000'),
  ('2020-06-14', NULL, '5', 'item 6', 'Each', '4', '2.5', '15', '8.5', '1.5', '3', '10', '0', '4', '10', '1', '1', '2', '3', '2020-06-15 11:00:00.000001');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 dry and chiller lines split Quantity; Total Excluding Tax = ExtendedPrice - TaxAmount; UnitPrice and…', missing, extra;
  END IF;
END $pp$;
CREATE TEMP TABLE pp_actual_ord ON COMMIT DROP AS
SELECT row_number() OVER () AS pp_ord, pp_r.* FROM (SELECT * FROM integration.get_sale_updates('2020-06-15 11:00:00.000000'::timestamp, '2020-06-15 13:00:00.000000'::timestamp)) AS pp_r;
CREATE TEMP TABLE pp_expected_ord (pp_ord bigint, LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected_ord VALUES
  (1, '2020-06-14', NULL, '1', 'dry item ', 'Each', '4', '2.5', '15', '8.5', '1.5', '3', '10', '4', '0', '10', '1', '2', '1', '3', '2020-06-15 12:00:00.000000'),
  (2, '2020-06-14', NULL, '1', 'item 2', 'Each', '4', NULL, '15', '8.5', '1.5', '3', '10', '0', '4', '10', '1', '2', '2', '3', '2020-06-15 12:00:01.000000'),
  (3, '2020-06-14', '2020-06-15', '4', 'item 5', 'Each', '4', '2.5', '15', '8.5', '1.5', '3', '10', '4', '0', '10', '1', '1', '1', '3', '2020-06-15 13:00:00.000000'),
  (4, '2020-06-14', NULL, '5', 'item 6', 'Each', '4', '2.5', '15', '8.5', '1.5', '3', '10', '0', '4', '10', '1', '1', '2', '3', '2020-06-15 11:00:00.000001');
DO $pp$
DECLARE got text[]; want text[];
BEGIN
  SELECT array_agg(ROW("WWI Invoice ID")::text ORDER BY pp_ord) INTO got FROM pp_actual_ord;
  SELECT array_agg(ROW("WWI Invoice ID")::text ORDER BY pp_ord) INTO want FROM pp_expected_ord;
  IF got IS DISTINCT FROM want THEN
    RAISE EXCEPTION 'agreed test failed (%): rows are not in the order the original returns (order key WWI Invoice ID)', 'test 01 dry and chiller lines split Quantity; Total Excluding Tax = ExtendedPrice - TaxAmount; UnitPrice and…';
  END IF;
END $pp$;
ROLLBACK;
